class InvariantErr(Exception):
    """Raised when an invariant check fails."""
    pass


class ModuleV2_11:
    """Distributed Consistency Module V2_11."""

    @staticmethod
    def check_invariant(p: dict) -> bool:
        """
        Enforces that check_invariant(p) returns True for p.get('valid') == True,
        raising InvariantErr otherwise.
        """
        if p.get('valid') is True:
            return True
        raise InvariantErr("Invariant check failed: 'valid' is not True.")
